function photoMarkup(a,small=false){const initials=String(a.name||'UP').split(/\s+/).slice(0,2).map(x=>x[0]).join('');const photo=a.photo||a.avatar||a.telegramPhoto||'';const safe=/^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(photo)||/^https:\/\/(?:t\.me|telegram\.org|[a-z0-9-]+\.telegram\.org)\/[^\s<>"\\]+$/i.test(photo);return `<div class="avatar athlete-avatar ${small?'small-avatar':''}"><span>${esc(initials)}</span>${safe?`<img class="athlete-photo" src="${esc(photo)}" alt="${esc(a.name||'Фото спортсмена')}" referrerpolicy="no-referrer">`:''}</div>`;}
