function showFollowerScreen(){if(!profile)return form();shell('followers');$('content').innerHTML=`<section class="panel"><h1>Обновить подписчиков</h1><p>Отчёт за ${esc(monthText(stats?.month))}. Укажите количество подписчиков на сегодняшний день в каждой своей соцсети.</p><button class="secondary compact-level" id="back-profile">Мой профиль</button></section>${socialMarkup(followers,true)}<p id="followers-saved" role="status"></p>`;$('back-profile').onclick=card;wireFollowers();}
function followerLanding(){const route=preview?new URLSearchParams(location.search).get('startapp'):new URLSearchParams(initData).get('start_param');if(route==='followers')showFollowerScreen();else card();}
function ownHighlightsMarkup(){return `<section class="panel"><div class="section-heading"><h2>Сильные публикации</h2><button id="add-highlight" class="secondary">Добавить</button></div><p class="small-note">Покажи публикацию, которой гордишься. Просмотры, лайки и комментарии вводятся вручную и будут видны администратору. Этот отчёт не добавляет ссылку повторно в общий счётчик.</p>${highlights.length?highlights.map((item,i)=>highlightMarkup(item,false,i)).join(''):'<p>Пока нет выделенных публикаций.</p>'}</section>`;}
function highlightMarkup(item,admin=false,index=0){return `<article class="highlight-card">${admin?`<div class="highlight-athlete">${photoMarkup(item.athlete,true)}<b>${esc(item.athlete.name)}</b></div>`:''}<div class="post-heading">${brandIcon(item.platform)}<span class="post-kind">${esc(linkKind(item))}</span>${!admin?`<button class="plain-button" data-highlight="${index}">Изменить</button>`:''}</div><a class="publication" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${esc(item.url)}</a><div class="engagement"><span><b>${numberText(item.views)}</b> просмотров</span><span><b>${numberText(item.likes)}</b> лайков</span><span><b>${numberText(item.comments)}</b> комментариев</span></div><small class="small-note">Обновлено ${esc(new Date(item.updatedAt).toLocaleDateString('ru-RU'))}</small></article>`;}
function myProfile(){shell('profile');const shown={...profile,photo:profile.photo||profile.avatar||profile.telegramPhoto||user?.photoUrl};$('content').innerHTML=profileMarkup(shown,true)+statsMarkup()+socialMarkup(followers,true)+ownHighlightsMarkup()+(canActivateAdmin?'<section class="panel"><h2>Управление командой</h2><p>Ваш аккаунт подготовлен для роли главного администратора.</p><button id="activate-admin" class="secondary">Активировать администратора</button></section>':'');$('edit').onclick=form;wireFollowers();$('add-highlight').onclick=()=>highlightDialog();document.querySelectorAll('[data-highlight]').forEach(b=>b.onclick=()=>highlightDialog(highlights[Number(b.dataset.highlight)]));if($('activate-admin'))$('activate-admin').onclick=adminDialog;wirePhotos();}
function form(){const a=profile||{};avatarDraft=a.avatar||'';const photo={name:a.name||user?.name,photo:avatarDraft||a.telegramPhoto||user?.photoUrl};$('screen').innerHTML=`<section class="panel"><h1>${profile?'Изменить профиль':'Регистрация спортсмена'}</h1><form id="profile"><div class="photo-editor"><div id="photo-preview">${photoMarkup(photo)}</div><p class="small-note">По умолчанию используем фото, которое передал Telegram.</p><label class="file-button" for="photo-input">Выбрать другое фото</label><input type="file" id="photo-input" accept="image/*" class="visually-hidden"><button type="button" id="telegram-photo" class="plain-button">Использовать фото Telegram</button><p id="photo-error" role="alert"></p></div><label for="name">Фамилия и имя</label><input id="name" required minlength="2" maxlength="120" value="${esc(a.name||user?.name||'')}"><label for="sport">Вид спорта</label><input id="sport" maxlength="100" value="${esc(a.sport||'')}"><label for="city">Город</label><input id="city" maxlength="100" value="${esc(a.city||'')}"><label for="bio">О себе и достижения</label><textarea id="bio" maxlength="500">${esc(a.bio||'')}</textarea><details ${profile?'open':''}><summary>Социальные сети — необязательно</summary><p class="small-note">Можно зарегистрироваться без единой ссылки и добавить соцсети позже через «Изменить профиль». Instagram и TikTok: введите @username или полную ссылку. Остальные соцсети: ссылку на профиль. Ненужные поля оставьте пустыми.</p>${PLATFORMS.map(platform=>`<label class="social-edit-label" for="social-${platform}">${brandIcon(platform)} ${esc(platform)}</label><input id="social-${platform}" type="${['Instagram','TikTok'].includes(platform)?'text':'url'}" autocapitalize="off" spellcheck="false" maxlength="500" placeholder="${SOCIAL_EXAMPLES[platform]}" value="${esc(a.socials?.[platform]||'')}">`).join('')}</details><div id="profile-error" role="alert"></div><div class="actions"><button id="save">${profile?'Сохранить':'Зарегистрироваться'}</button>${!profile?'<button type="submit" formnovalidate id="skip-socials" class="secondary">Зарегистрироваться без соцсетей</button>':''}${profile?'<button type="button" id="cancel" class="secondary">Отмена</button>':''}</div></form></section>`;$('profile').onsubmit=save;if($('cancel'))$('cancel').onclick=card;$('photo-input').onchange=selectPhoto;$('telegram-photo').onclick=()=>{avatarDraft='';$('photo-preview').innerHTML=photoMarkup({name:a.name||user?.name,photo:a.telegramPhoto||user?.photoUrl});wirePhotos();};wirePhotos();}
async function selectPhoto(e){const file=e.target.files[0];if(!file)return;$('photo-error').textContent='';$('save').disabled=true;try{if(file.size>12*1024*1024)throw Error('Выберите фото размером до 12 МБ.');const url=URL.createObjectURL(file);let image;try{image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Не удалось прочитать фото. Попробуйте JPEG или PNG.'));img.src=url;});}finally{URL.revokeObjectURL(url);}const canvas=document.createElement('canvas'),size=192;canvas.width=canvas.height=size;const side=Math.min(image.naturalWidth,image.naturalHeight);if(!side)throw Error('Пустое изображение.');const context=canvas.getContext('2d');context.fillStyle='#191b20';context.fillRect(0,0,size,size);context.drawImage(image,(image.naturalWidth-side)/2,(image.naturalHeight-side)/2,side,side,0,0,size,size);let data='';for(const quality of [.8,.65,.5,.35]){data=canvas.toDataURL('image/jpeg',quality);if(data.length<=22000)break;}if(data.length>22000)throw Error('Фото слишком сложное для загрузки. Выберите другое.');avatarDraft=data;$('photo-preview').innerHTML=photoMarkup({name:$('name').value,photo:data});wirePhotos();}catch(err){$('photo-error').textContent=err.message;}finally{$('save').disabled=false;}}
async function save(e){e.preventDefault();$('save').disabled=true;if($('skip-socials'))$('skip-socials').disabled=true;const next={avatar:avatarDraft,socials:{}};for(const k of ['name','sport','city','bio'])next[k]=$(k).value.trim();if(e.submitter?.id!=='skip-socials')for(const platform of PLATFORMS){const value=$('social-'+platform).value.trim();if(value)next.socials[platform]=value;}try{for(const platform of ['Instagram','TikTok'])if(next.socials[platform])next.socials[platform]=socialInputUrl(platform,next.socials[platform]);if(preview){profile={...next,photo:next.avatar||profile?.telegramPhoto||''};followers=PLATFORMS.filter(p=>next.socials[p]).map(platform=>({platform,url:next.socials[platform],count:null,delta:null}));}else{const data=await api('/api/profile','PUT',next);profile=data.profile;stats=data.stats;followers=data.followers;}rankingCache.clear();$('status').textContent=preview?'Макет: изменения только на этом экране.':'Профиль сохранён.';followerLanding();}catch(err){$('status').textContent='Не удалось сохранить. '+err.message;$('profile-error').textContent=err.message;$('save').disabled=false;if($('skip-socials'))$('skip-socials').disabled=false;}}
function dialogShell(title,body){const dialog=document.createElement('dialog');dialog.className='feature-dialog';dialog.innerHTML=`<button type="button" class="secondary close">Закрыть</button><h2>${esc(title)}</h2>${body}<p class="dialog-error" role="alert"></p>`;document.body.append(dialog);dialog.querySelector('.close').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();return dialog;}
function followerDialog(platform){const item=followers.find(x=>x.platform===platform);if(!item)return;const month=stats?.month||new Date().toISOString().slice(0,7);const d=dialogShell(platform+' · подписчики',`<p>Отчёт за ${esc(monthText(month))}. ${item.previous===null||item.previous===undefined?'За прошлый месяц пока нет отчёта.':'В прошлом месяце: '+numberText(item.previous)+'.'}</p><form><label for="follower-number">Сколько подписчиков сейчас?</label><input id="follower-number" type="number" inputmode="numeric" required min="0" max="10000000000" step="1" value="${item.current??''}"><div class="actions"><button>Сохранить отчёт</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=d.querySelector('form button:not([type="button"])');button.disabled=true;try{if(preview)throw Error('Отчёт сохраняется только внутри Telegram.');const data=await api('/api/followers','POST',{platform,count:Number(d.querySelector('input').value)});followers=data.followers;if(data.month&&stats)stats.month=data.month;rankingCache.clear();d.close();if(currentTab==='followers'){showFollowerScreen();$('followers-saved').textContent='Количество подписчиков сохранено.';}else if(currentTab==='profile')card();}catch(err){d.querySelector('.dialog-error').textContent=err.message;button.disabled=false;}};}
function highlightDialog(item){const d=dialogShell(item?'Статистика публикации':'Сильная публикация',`<p>Укажите публикацию и её текущие показатели. Эти данные вводятся вручную.</p><form><label for="highlight-url">Ссылка на публикацию</label><input id="highlight-url" type="url" required maxlength="2048" value="${esc(item?.url||'')}" ${item?'readonly':''}>${[['views','Просмотры'],['likes','Лайки'],['comments','Комментарии']].map(([key,label])=>`<label for="highlight-${key}">${label}</label><input id="highlight-${key}" type="number" inputmode="numeric" min="0" max="1000000000000" step="1" required value="${item?.[key]??''}">`).join('')}<div class="actions"><button>Отправить статистику</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=d.querySelector('form button:not([type="button"])');button.disabled=true;try{if(preview)throw Error('Статистика сохраняется только внутри Telegram.');const body={url:d.querySelector('#highlight-url').value.trim()};for(const key of ['views','likes','comments'])body[key]=Number(d.querySelector('#highlight-'+key).value);const data=await api('/api/highlights','POST',body);highlights=data.items;adminHighlightsCache=null;d.close();if(currentTab==='profile')card();}catch(err){d.querySelector('.dialog-error').textContent=err.message;button.disabled=false;}};}
async function showAdminHighlights(){if(!adminHighlightsCache)adminHighlightsCache=(await api('/api/admin/highlights')).items;if(currentTab!=='admin')return;$('content').innerHTML=`<section class="panel"><div class="section-heading"><h1>Популярные публикации</h1><button id="refresh-highlights" class="secondary">Обновить</button></div><p class="small-note">Отчёты спортсменов, отсортированные по просмотрам. Показатели внесены вручную, автоматической проверки содержания нет.</p>${adminHighlightsCache.length?adminHighlightsCache.map(item=>highlightMarkup(item,true)).join(''):'<p>Спортсмены ещё не выделили публикации.</p>'}</section>`;$('refresh-highlights').onclick=()=>{adminHighlightsCache=null;navigate('admin');};wirePhotos();}
function adminDialog(){const d=dialogShell('Активация администратора','<p>Введите одноразовый код владельца проекта. Он действует только для подготовленного Telegram-аккаунта.</p><form><label for="admin-code">Одноразовый код</label><input id="admin-code" type="password" required autocomplete="one-time-code" autocapitalize="off" spellcheck="false"><div class="actions"><button>Активировать</button></div></form>');d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('form button');b.disabled=true;try{await api('/api/admin/activate','POST',{code:d.querySelector('input').value.trim()});isAdmin=true;isOwner=true;canActivateAdmin=false;d.close();card();}catch(err){d.querySelector('.dialog-error').textContent=err.message;b.disabled=false;}};}

async function init(){if(preview){user={name:'Александр Тестовый'};publicationCache=[{platform:'VK',url:'https://vk.ru/clip-123_456',kind:'clip'},{platform:'Instagram',url:'https://instagram.com/reel/DEMO/',kind:'reels'},{platform:'TikTok',url:'https://tiktok.com/@demo/video/123?share='+('a'.repeat(220)),kind:'video'},{platform:'Telegram',url:'https://t.me/demo/s/123',kind:'story'},{platform:'MAX',url:'https://max.ru/demo/123',kind:'publication'},{platform:'YouTube',url:'https://youtube.com/shorts/DEMO123',kind:'shorts'}].map((p,i)=>({...p,id:'demo-'+i,created_at:'2026-10-31T10:00:00Z'}));profile={name:'Александр Тестовый',sport:'Тяжёлая атлетика',city:'Тюмень',bio:'Проверяем кабинет внутри Telegram. Это вымышленный профиль.',socials:{Instagram:'https://instagram.com/demo',TikTok:'https://tiktok.com/@demo'}};stats={month:'2026-10',monthPublications:6,total:6,rank:3,level:'0'};followers=[{platform:'Instagram',url:profile.socials.Instagram,count:12400,current:12400,previous:12000,delta:400,month:'2026-10'},{platform:'TikTok',url:profile.socials.TikTok,count:6800,current:6800,previous:7100,delta:-300,month:'2026-10'}];highlights=[{id:'demo-highlight',url:'https://instagram.com/reel/DEMO/',platform:'Instagram',views:125000,likes:8400,comments:230,updatedAt:'2026-10-31T10:00:00Z'}];if(new URLSearchParams(location.search).get('startapp')==='followers'){stats.month='2026-11';followers=followers.map(x=>({...x,current:null,delta:null}));profile.socials.YouTube='https://youtube.com/@demo';followers.push({platform:'YouTube',url:profile.socials.YouTube,count:null,current:null,month:null,delta:null});}isAdmin=new URLSearchParams(location.search).get('role')==='admin';isOwner=isAdmin;adminUsersCache={isOwner,items:[{id:'demo-me',...profile,links:6,isOwner:true,isAdmin:true,isSelf:true},{id:'demo-new',name:'Мария Примерова',sport:'Бег',city:'Казань',links:0,isOwner:false,isAdmin:false,isSelf:false}]};adminHighlightsCache=highlights.map(h=>({...h,athlete:{...profile}}));const demoRanking={myId:'demo-me',items:[{id:'demo-me',...profile,links:6,rank:1,followersTotal:19200,level:'0'}]};rankingCache.set('all',demoRanking);rankingCache.set('0',demoRanking);if(new URLSearchParams(location.search).get('athlete')==='1'){$('screen').innerHTML=profileMarkup({...profile,links:0,level:'0'});}else if(new URLSearchParams(location.search).get('signup')==='1'){profile=null;form();}else followerLanding();return;}$('screen').innerHTML=loading();try{if(window.upTelegramReady)await window.upTelegramReady;const tg=window.Telegram?.WebApp;if(!tg?.initData)throw Error('Откройте приложение кнопкой бота в Telegram.');tg.ready();tg.expand();initData=tg.initData;if(location.hash)history.replaceState(null,'',location.pathname+location.search);const result=await api('/api/profile');user=result.user;profile=result.profile;publicationCache=result.items;stats=result.stats;ownMonths=result.months||[];followers=result.followers||[];highlights=result.highlights||[];isAdmin=!!result.isAdmin;isOwner=!!result.isOwner;canActivateAdmin=!!result.canActivateAdmin;$('status').textContent='Вы вошли через Telegram.';if(profile)followerLanding();else form();}catch(e){$('status').textContent='Не удалось открыть кабинет. '+e.message;$('screen').innerHTML='<p>Закройте Mini App и откройте его заново. Если ошибка повторяется, сообщите администратору.</p>';}}
init();

async function showAdminUsers(){
 if(!adminUsersCache)adminUsersCache=await api('/api/admin/users');if(currentTab!=='users')return;
 const data={...adminUsersCache,items:showDeletedUsers?(adminUsersCache.archived||[]):adminUsersCache.items};$('content').innerHTML=`<section class="panel"><div class="section-heading"><h1>${showDeletedUsers?'Удалённые':'Участники'} · ${data.items.length}</h1><button class="secondary" id="refresh-users">Обновить</button></div><p>Все зарегистрированные спортсмены, в том числе без публикаций. ${data.isOwner?'Вы — главный администратор. Можно назначать и снимать администраторов.':'Назначать администраторов может только главный администратор.'}</p>${data.isOwner?'<div class="filters"><button id="active-users">Участники</button><button id="deleted-users" class="secondary">Удалённые</button></div>':''}<label for="user-search">Поиск по имени, спорту или городу</label><input id="user-search" type="search" placeholder="Найти участника"><div id="user-list"></div></section>`;
 const render=()=>{const q=$('user-search').value.trim().toLocaleLowerCase('ru');const items=data.items.filter(a=>[a.name,a.sport,a.city].join(' ').toLocaleLowerCase('ru').includes(q));$('user-list').innerHTML=items.map(a=>`<article class="highlight-card"><div class="highlight-athlete">${photoMarkup(a,true)}<b>${esc(a.name)}${a.isSelf?' · Вы':''}</b></div><p>${esc([a.sport,a.city].filter(Boolean).join(' · '))}</p><p>${a.isOwner?'Главный администратор':a.isAdmin?'Администратор':'Спортсмен'} · ${esc(memberLevelText(a.level))} · Публикаций: ${numberText(a.links)}</p><div class="actions">${a.deletedAt?`<button class="secondary" data-restore-id="${esc(a.id)}">Восстановить профиль</button>`:`<button class="secondary" data-user-profile="${esc(a.id)}">Профиль</button>${!a.isOwner||data.isOwner?`<button class="secondary" data-level-id="${esc(a.id)}">Изменить уровень</button>`:''}`}${data.isOwner&&!a.isOwner&&!a.deletedAt?`<button class="secondary" data-role-id="${esc(a.id)}">${a.isAdmin?'Снять администратора':'Назначить администратором'}</button><button class="danger-outline" data-delete-id="${esc(a.id)}">Удалить профиль</button>`:''}</div></article>`).join('')||'<p>Участники не найдены.</p>';document.querySelectorAll('[data-user-profile]').forEach(b=>b.onclick=()=>openAthlete(b.dataset.userProfile));document.querySelectorAll('[data-role-id]').forEach(b=>b.onclick=()=>roleDialog(data.items.find(a=>a.id===b.dataset.roleId)));document.querySelectorAll('[data-level-id]').forEach(b=>b.onclick=()=>memberLevelDialog(data.items.find(a=>a.id===b.dataset.levelId)));document.querySelectorAll('[data-delete-id]').forEach(b=>b.onclick=()=>memberDeleteDialog(data.items.find(a=>a.id===b.dataset.deleteId)));document.querySelectorAll('[data-restore-id]').forEach(b=>b.onclick=()=>memberRestoreDialog(data.items.find(a=>a.id===b.dataset.restoreId)));wirePhotos();};$('user-search').oninput=render;render();$('refresh-users').onclick=()=>{adminUsersCache=null;navigate('users');};if(data.isOwner){$('active-users').onclick=()=>{showDeletedUsers=false;showAdminUsers();};$('deleted-users').onclick=()=>{showDeletedUsers=true;showAdminUsers();};}
}
function roleDialog(athlete){const role=athlete.isAdmin?'athlete':'admin';const d=dialogShell(role==='admin'?'Назначить администратора':'Снять администратора',`<p><b>${esc(athlete.name)}</b></p><p>${role==='admin'?'Получит доступ ко всем участникам и отчётам команды. Назначать других администраторов сможет только главный администратор.':'Доступ к управлению командой будет закрыт. Профиль и публикации сохранятся.'}</p><form><button>${role==='admin'?'Подтвердить назначение':'Подтвердить снятие'}</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('form button');b.disabled=true;try{if(preview)throw Error('В макете права не изменяются.');adminUsersCache=await api('/api/admin/role','POST',{id:athlete.id,role});d.close();if(currentTab==='users')await showAdminUsers();}catch(err){d.querySelector('.dialog-error').textContent=err.message;b.disabled=false;}};}

function socialInputUrl(platform,value){if(/^https:\/\//i.test(value))return value;const name=value.replace(/^@/,'');if(!name||name.length>(platform==='Instagram'?30:24)||! /^[A-Za-z0-9_]+(?:[.][A-Za-z0-9_]+)*$/.test(name))throw Error(platform+': введите @username латинскими буквами, цифрами, точками или подчёркиваниями, либо полную ссылку.');return platform==='Instagram'?'https://instagram.com/'+name:'https://tiktok.com/@'+name;}

function publicSocialLinks(socials){const items=PLATFORMS.filter(p=>socials[p]);if(!items.length)return '';return `<section class="panel public-socials"><h2>Социальные сети</h2><div class="social-links">${items.map(p=>`<a href="${esc(socials[p])}" class="social-link" target="_blank" rel="noopener noreferrer" aria-label="Открыть ${esc(p)}">${brandIcon(p)}<span>${esc(p)}</span><span aria-hidden="true">↗</span></a>`).join('')}</div></section>`;}

let showDeletedUsers=false;
const MEMBER_LEVELS=[['0','Уровень 0'],['1','Уровень 1'],['2','Уровень 2'],['3','Уровень 3'],['Ambassador','Амбассадор']];
function memberLevelText(value){return MEMBER_LEVELS.find(([v])=>v===(value||'0'))?.[1]||'Уровень 0';}
function memberLevelDialog(member,onSaved){
 let chosen=member.level||'0';
 const d=dialogShell('Изменить уровень',`<p>${esc(member.name)}</p><form><div class="level-options" role="group" aria-label="Новый уровень">${MEMBER_LEVELS.map(([v,label])=>`<button type="button" data-pick-level="${v}" aria-pressed="${chosen===v}" class="${chosen===v?'':'secondary'}">${v==='Ambassador'?'Амбассадор':v}</button>`).join('')}</div><button type="submit">Сохранить</button></form>`);
 d.querySelectorAll('[data-pick-level]').forEach(b=>b.onclick=()=>{chosen=b.dataset.pickLevel;d.querySelectorAll('[data-pick-level]').forEach(x=>{x.classList.toggle('secondary',x.dataset.pickLevel!==chosen);x.setAttribute('aria-pressed',String(x.dataset.pickLevel===chosen));});});
 memberMutation(d,'/api/admin/level',()=>({id:member.id,level:chosen}),member,onSaved);
}
function memberDeleteDialog(member){
 const d=dialogShell('Удалить профиль',`<p><b>${esc(member.name)}</b></p><p>Профиль исчезнет из команды и рейтинга, вход будет закрыт. Данные можно восстановить из раздела «Удалённые». Права администратора будут сняты.</p><form><label for="delete-confirm">Для подтверждения введите: ${esc(member.name)}</label><input id="delete-confirm" required autocomplete="off" autocapitalize="off"><button class="danger-outline">Удалить профиль</button></form>`);
 memberMutation(d,'/api/admin/delete',()=>({id:member.id,confirmName:d.querySelector('input').value}),member);
}
function memberRestoreDialog(member){
 const d=dialogShell('Восстановить профиль',`<p>Вернуть профиль ${esc(member.name)} и его публикации? Права администратора при необходимости нужно назначить заново.</p><form><button>Восстановить профиль</button></form>`);
 memberMutation(d,'/api/admin/restore',()=>({id:member.id}),member);
}
function memberMutation(d,path,payload,member,onSaved){d.querySelector('form').onsubmit=async e=>{
 e.preventDefault();const button=d.querySelector('form button:not([type="button"])');button.disabled=true;
 try{if(preview)throw Error('В макете данные участников не изменяются.');const body=payload();adminUsersCache=await api(path,'POST',body);if(path==='/api/admin/level'&&member.isSelf){if(profile)profile.level=body.level;if(stats)stats.level=body.level;}rankingCache.clear();monthlyCache.clear();adminHighlightsCache=null;d.close();if(onSaved)onSaved(body.level);if(currentTab==='users')await showAdminUsers();else if(currentTab==='ranking')await showRanking();}
 catch(err){d.querySelector('.dialog-error').textContent=err.message;button.disabled=false;}
 };}

function contactMarkup(a){return /^https:\/\/t\.me\/[A-Za-z][A-Za-z0-9_]{3,31}$/.test(a.contactUrl||'')?`<a class="athlete-contact" href="${esc(a.contactUrl)}" data-telegram-contact>↗ Написать</a>`:'';}
function wireContacts(root){root.querySelectorAll('[data-telegram-contact]').forEach(a=>a.onclick=e=>{const tg=window.Telegram?.WebApp;if(tg?.openTelegramLink){e.preventDefault();tg.openTelegramLink(a.href);}});}

function monthlyPreviewData(month){const selected=month||'2026-10',members=[{id:'demo-me',...profile,level:'1',matched:true,rank:1,links:3,followersTotal:selected==='2026-10'?19200:20000,followersKnown:true,needsReview:0},{id:'legacy-demo',name:'Спортсмен без кабинета',sport:'',city:'',level:'0',matched:false,rank:2,links:1,followersTotal:0,followersKnown:false,needsReview:0}];return {ok:true,month:selected,months:['2026-11','2026-10'],items:members,total:4};}
async function showMonthlyTeam(){
 if(!isAdmin)return;const chosen=monthlyMonth;let data=monthlyCache.get(chosen);if(!data){data=preview?monthlyPreviewData(chosen):await api('/api/monthly/team','POST',{month:chosen});if(currentTab!=='monthly'||monthlyMonth!==chosen)return;monthlyMonth=data.month;monthlyCache.set(data.month,data);}const month=data.month;
 $('content').innerHTML=`<section class="panel"><h1>Разбор месяца</h1><div class="month-heading"><label for="review-month">Месяц отчёта</label><select id="review-month">${data.months.map(m=>`<option value="${esc(m)}" ${m===month?'selected':''}>${esc(monthText(m))}</option>`).join('')}</select><button class="secondary compact-level" id="monthly-refresh">Обновить</button></div><p class="small-note">${numberText(data.items.length)} участников · ${numberText(data.total)} ссылок. Порядок — по количеству ссылок за выбранный месяц. Подписчики — по отчётам не позднее этого месяца; отсутствие отчёта обозначено прочерком.</p>${month==='2026-10'?'<p class="archive-note">Октябрь — разовый импорт старой таблицы. Время у ссылок — исходная отправка отчёта. Ссылки с отметкой «Проверить» требуют внимания.</p>':''}<label for="monthly-search">Поиск спортсмена</label><input type="search" id="monthly-search" placeholder="Имя спортсмена"></section><div class="list" id="monthly-list"></div>`;
 const render=()=>{const q=$('monthly-search').value.trim().toLowerCase(),items=data.items.filter(a=>a.name.toLowerCase().includes(q));$('monthly-list').innerHTML=items.map(a=>`<button class="panel rank-row" data-month-athlete="${esc(a.id)}"><b class="rank-position">#${a.rank}</b>${photoMarkup(a,true)}<span>${esc(a.name)}<small>${a.matched?esc(memberLevelText(a.level)):'Нет кабинета · архив'}${a.needsReview?' · проверить '+a.needsReview:''}</small></span><span class="rank-metrics"><b>${numberText(a.links)}</b><small>ссылок</small><b>${a.followersKnown?numberText(a.followersTotal):'—'}</b><small>подписчиков</small></span></button>`).join('')||'<p>За этот месяц публикаций не найдено.</p>';document.querySelectorAll('[data-month-athlete]').forEach(b=>b.onclick=()=>openMonthlyAthlete(b.dataset.monthAthlete));wirePhotos();};$('monthly-search').oninput=render;render();
 $('review-month').onchange=e=>{monthlyMonth=e.target.value;navigate('monthly');};$('monthly-refresh').onclick=()=>{monthlyCache.delete(monthlyMonth);navigate('monthly');};
}
function monthlyPostsMarkup(items){return `<div class="list">${items.map(a=>`<article class="panel post-card"><div class="post-heading">${brandIcon(a.platform)}<span class="post-kind">${esc(linkKind(a))}</span><time>${esc(new Date(a.created_at).toLocaleDateString('ru-RU',{timeZone:'Asia/Yekaterinburg'}))}</time></div><p class="small-note">${a.imported?'Архив · исходная отправка отчёта':'Отправлено в приложении'}${a.sourceCell?' · '+esc(a.sourceCell):''}${a.needsReview?' · Требует проверки':''}</p><a class="publication" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.url)}</a></article>`).join('')}</div>`;}
async function openMonthlyAthlete(id){
 const month=monthlyMonth;$('content').innerHTML=loading();try{let team=monthlyCache.get(month);if(!team){team=preview?monthlyPreviewData(month):await api('/api/monthly/team','POST',{month});monthlyCache.set(month,team);}let data;if(preview){const a=team.items.find(x=>x.id===id);data={month,athlete:{...a,followers:[],contactUrl:''},items:(publicationCache||[]).slice(0,a.links).map(x=>({...x,imported:true,month})),highlights:[]};}else data=await api('/api/monthly/athlete','POST',{month,id});if(currentTab!=='monthly'||monthlyMonth!==month)return;
 const a=data.athlete,index=team.items.findIndex(x=>x.id===id),next=team.items[index+1];$('content').innerHTML=`<div class="monthly-navigation"><button class="secondary compact-level" id="monthly-back">← Все спортсмены</button><b>${esc(monthText(month))}</b>${next?'<button class="secondary compact-level" id="monthly-next">Следующий →</button>':''}</div>${profileMarkup({...a,rank:null})}${a.matched?'<div class="profile-admin-actions"><button class="secondary compact-level" id="monthly-level">Изменить уровень</button></div>':'<p class="archive-note">Этот спортсмен пока не сопоставлен с кабинетом. Ссылки сохранены в архиве; чужому аккаунту они не присвоены.</p>'}<section class="panel monthly-audience"><h2>Подписчики за период</h2>${a.followers?.length?a.followers.map(f=>`<p><b>${esc(f.platform)}: ${numberText(f.count)}</b> · ${f.month?esc(monthText(f.month)):'нет отчёта'}${f.delta!==null&&f.delta!==undefined?' · '+(f.delta>0?'+':'')+numberText(f.delta)+' за месяц':''}</p>`).join(''):'<p>Исторических сведений о подписчиках нет. Текущие числа за другой месяц не подставляются.</p>'}</section><section class="panel"><h2>Сильные публикации</h2><p class="small-note">Показатели внесены спортсменом; дата измерения указана у публикации.</p>${data.highlights.length?data.highlights.map(h=>highlightMarkup(h,true)).join(''):'<p>Выделенных публикаций за этот период нет.</p>'}</section><h2>Все ссылки · ${data.items.length}</h2>${monthlyPostsMarkup(data.items)}<div class="monthly-navigation"><button class="secondary" id="monthly-back-bottom">К списку спортсменов</button></div>`;
 $('monthly-back').onclick=showMonthlyTeam;$('monthly-back-bottom').onclick=showMonthlyTeam;if(next)$('monthly-next').onclick=()=>openMonthlyAthlete(next.id);if($('monthly-level'))$('monthly-level').onclick=()=>memberLevelDialog({...a,id},()=>{monthlyCache.clear();openMonthlyAthlete(id);});wirePhotos();wireContacts(document);
 }catch(e){if(currentTab==='monthly')$('content').innerHTML='<p>Не удалось открыть разбор: '+esc(e.message)+'</p><button id="monthly-retry">К списку</button>';if($('monthly-retry'))$('monthly-retry').onclick=showMonthlyTeam;}
}
